def fm_channels(region):
    if region == "EU": lo, hi, step = 87_500, 108_000, 100
    else:              lo, hi, step = 88_100, 107_900, 200
    return list(range(lo, hi + 1, step))

def seek_up(cur, region, good):
    ch = fm_channels(region); i = ch.index(cur)
    for f in ch[i + 1:] + ch[:i + 1]:
        if f in good:
            return f

print(len(fm_channels("EU")), len(fm_channels("US")))
print(seek_up(98_100, "US", {101_100, 95_900}))
print(seek_up(107_900, "US", {101_100, 95_900}))

def db_to_gain(db):
    return 10 ** (db / 20)

for db in (0, -6, -20, -40):
    print(db, "dB ->", round(db_to_gain(db), 4))
print("-6dB sample =", int(32767 * db_to_gain(-6)))
